                                        <code class="text-gray-400">HEADROOM_OUTPUT_HOLDOUT=0.05</code>
                                        to measure it for real.
                                    </div>
                                </template>
                            </div>
                        </template>
                        <template x-if="!stats.tokens?.output_reduction?.available">
                            <div class="mt-1 text-xs text-gray-500 leading-relaxed">
                                <span class="text-2xl font-light tabular-nums text-gray-600">—</span>
                                <div class="mt-1">Output shaping is off. Set
                                    <code class="text-gray-400">HEADROOM_OUTPUT_SHAPER=1</code>
