                    <template x-for="row in (stats.savings?.by_source || [])" :key="row.source + ':' + row.realized">
                        <div class="bg-surface rounded-lg p-4 border border-border">
                            <div class="text-xs text-gray-500 uppercase tracking-wide mb-1"
