                            </div>
                            <div class="mt-1 text-xs text-gray-600 leading-relaxed"
                                 x-text="formatNumber(row.events || 0) + ' calls \xb7 ' + (row.realized ? 'realized' : 'projected')"></div>
                        </div>
                    </template>
                </div>

                <!-- Performance -->
                <div class="grid grid-cols-1 gap-4 mb-6 lg:grid-cols-3">
                    <!-- Headroom Overhead -->
