                                <div class="text-sm text-gray-500 italic">No requests yet</div>
                            </template>
                        </div>
                    </div>

                    <!-- Per-Model Savings Breakdown -->
                    <template x-if="Object.keys(stats.cost?.per_model || {}).length > 0">
                        <div class="bg-surface rounded-lg border border-border overflow-hidden lg:col-span-2">
                            <div class="px-4 py-3 border-b border-border flex justify-between items-center">
                                <span class="text-sm font-medium text-gray-300">Per-Model Token Savings</span>
                                <span class="text-xs text-gray-500">Exact tokens saved per model</span>
                            </div>
                            <div class="overflow-x-auto">
                                <table class="w-full text-sm" style="table-layout:fixed">
                                    <colgroup>
                                        <col style="width:40%">
                                        <col style="width:12%">
                                        <col style="width:18%">
                                        <col style="width:18%">
                                        <col style="width:12%">
                                    </colgroup>
                                    <thead>
                                        <tr class="text-xs text-gray-500 uppercase tracking-wide">
                                            <th class="px-4 py-3 font-medium text-left">Model</th>
                                            <th class="px-4 py-3 font-medium text-right">Requests</th>
                                            <th class="px-4 py-3 font-medium text-right">Tokens Saved</th>
                                            <th class="px-4 py-3 font-medium text-right">Tokens Sent</th>
                                            <th class="px-4 py-3 font-medium text-right">Reduction</th>
                                        </tr>
                                    </thead>
                                    <tbody class="divide-y divide-border">
                                        <template x-for="[model, info] in Object.entries(stats.cost?.per_model || {})" :key="model">
                                            <tr class="hover:bg-border/30 transition-colors">
                                                <td class="px-4 py-3 text-left">
                                                    <span class="px-2 py-0.5 bg-border rounded text-xs" x-text="truncateModel(model)"></span>
                                                </td>
                                                <td class="px-4 py-3 text-right font-mono tabular-nums" x-text="info.requests"></td>
                                                <td class="px-4 py-3 text-right font-mono tabular-nums text-accent" x-text="formatNumber(info.tokens_saved)" :title="formatNumber(info.compression_tokens_saved || 0) + ' from compression \xb7 ' + formatNumber(info.tool_tokens_saved || 0) + ' from deferred tool schemas'"></td>
                                                <td class="px-4 py-3 text-right font-mono tabular-nums" x-text="formatNumber(info.tokens_sent)"></td>
                                                <td class="px-4 py-3 text-right">
                                                    <span class="text-accent font-mono tabular-nums" x-text="info.reduction_pct.toFixed(1) + '%'"></span>
                                                </td>
                                            </tr>
                                        </template>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </template>
                </div>

                <!-- Model Routing: shown only when a routing-stats provider is
                     registered (stats.routing; see headroom.proxy.routing_stats). -->
                <template x-if="(stats.routing?.pairs || []).length > 0">
                    <div class="bg-surface rounded-lg p-4 border border-border mb-6">
                        <div class="flex items-center justify-between mb-1">
                            <span class="text-sm font-medium text-gray-300">Model Routing</span>
                            <span class="text-xs text-gray-500 font-mono"
                                  x-text="(stats.routing.downgrades || 0) + ' downgraded \xb7 ' + (stats.routing.upgrades || 0) + ' upgraded \xb7 ' + (stats.routing.unchanged || 0) + ' unchanged \xb7 ' + formatNumber(stats.routing.decisions || 0) + ' decisions'"></span>
                        </div>
                        <!-- Two windows, one box. Session answers "is this working for ME,
                             right now"; lifetime answers "what has this layer been worth".
                             Neither substitutes for the other: routing savings accrue across
                             sessions, so session-only understates the layer badly, while a
                             lifetime total moves ~0.1% per turn and looks frozen during a
                             live demo. -->
                        <div class="grid grid-cols-2 gap-3 mb-4">
                            <!-- THIS SESSION -->
                            <div class="bg-bg rounded px-3 py-2 border border-border">
                                <div class="flex items-center gap-1.5 mb-1">
                                    <span class="relative flex h-2 w-2" x-show="(stats.routing.session?.decisions || 0) > 0">
                                        <span class="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                                        <span class="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                                    </span>
                                    <span class="text-xs text-gray-400 uppercase tracking-wide">This session</span>
                                </div>
                                <div class="text-xl font-semibold tabular-nums"
                                     :class="(stats.routing.session?.savings_usd || 0) > 0 ? 'text-emerald-400' : 'text-gray-500'"
                                     x-text="'$' + formatCurrency(stats.routing.session?.savings_usd || 0)"></div>
                                <div class="text-xs text-gray-500 font-mono mt-0.5"
                                     x-text="formatNumber(stats.routing.session?.decisions || 0) + ' decisions \xb7 '
                                             + (stats.routing.session?.downgrades || 0) + ' downgraded \xb7 '
                                             + (stats.routing.session?.unchanged || 0) + ' kept'"></div>
                                <!-- "Kept" is the router working, not idling: against a warm
                                     prefix cache, switching costs a cold write on the target
                                     that usually exceeds the cheaper per-token rate. Without
                                     this the panel reads as broken during exactly the
                                     sessions where the router is behaving correctly. -->
                                <div class="text-xs text-gray-600 mt-1 leading-snug"
                                     x-show="(stats.routing.session?.decisions || 0) > 0
                                             && (stats.routing.session?.downgrades || 0) === 0"
                                     title="Every turn was evaluated. Keeping the model is the correct call when the prefix cache is warm — switching would pay a cold write on the target.">
                                    Evaluating every turn; cache is warm, so switching would cost more than it saves.
                                </div>
                            </div>
                            <!-- ALL TIME -->
                            <div class="bg-bg rounded px-3 py-2 border border-border">
                                <div class="text-xs text-gray-400 uppercase tracking-wide mb-1">All time</div>
                                <div class="text-xl font-semibold tabular-nums"
                                     :class="(stats.routing.savings_usd || 0) > 0 ? 'text-emerald-400' : 'text-gray-500'"
                                     x-text="'$' + formatCurrency(stats.routing.savings_usd || 0)"></div>
                                <div class="text-xs text-gray-500 font-mono mt-0.5"
                                     x-text="formatNumber(stats.routing.decisions || 0) + ' decisions \xb7 '
                                             + (stats.routing.downgrades || 0) + ' downgraded \xb7 '
                                             + (stats.routing.unchanged || 0) + ' kept'"></div>
                                <div class="text-xs text-gray-600 mt-1 leading-snug">
                                    Survives restarts — kept in routemegood's decision log, not proxy memory.
                                </div>
                            </div>
                        </div>
                        <div class="text-xs text-gray-500 mb-2">Every decision on record, by requested → served pair</div>
                        <div class="overflow-x-auto">
                            <table class="w-full text-sm">
                                <thead>
                                    <tr class="text-xs text-gray-500 uppercase tracking-wide text-left">
                                        <th class="py-1 pr-2 font-medium">Requested</th>
                                        <th class="py-1 pr-2 font-medium"></th>
                                        <th class="py-1 pr-4 font-medium">Served</th>
                                        <th class="py-1 pr-4 font-medium text-right">Requests</th>
                                        <th class="py-1 pr-4 font-medium text-right">Enforced</th>
                                        <th class="py-1 pr-4 font-medium text-right">Holdout</th>
                                        <th class="py-1 pr-4 font-medium text-right">Measured</th>
                                        <th class="py-1 font-medium text-right">Saved</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <template x-for="p in stats.routing.pairs" :key="p.requested + '>' + p.served">
                                        <tr class="border-t border-border">
                                            <td class="py-1.5 pr-2 font-mono text-xs" x-text="p.requested"></td>
                                            <td class="py-1.5 pr-2 text-xs"
                                                :class="p.direction === 'downgrade' ? 'text-emerald-400' : (p.direction === 'upgrade' ? 'text-amber-400' : 'text-gray-500')"
                                                x-text="p.direction === 'downgrade' ? '↓' : (p.direction === 'upgrade' ? '↑' : '→')"></td>
                                            <td class="py-1.5 pr-4 font-mono text-xs" x-text="p.served"></td>
                                            <td class="py-1.5 pr-4 text-right tabular-nums" x-text="formatNumber(p.count)"></td>
                                            <td class="py-1.5 pr-4 text-right tabular-nums" x-text="formatNumber(p.enforced)"></td>
                                            <td class="py-1.5 pr-4 text-right tabular-nums text-gray-500" x-text="formatNumber(p.holdout)"></td>
                                            <td class="py-1.5 pr-4 text-right tabular-nums text-gray-500" x-text="formatNumber(p.measured)"></td>
                                            <td class="py-1.5 text-right tabular-nums"
                                                :class="p.savings_usd > 0 ? 'text-emerald-400' : (p.savings_usd < 0 ? 'text-red-400' : 'text-gray-500')"
                                                x-text="(p.savings_usd < 0 ? '-$' : '$') + formatCurrency(Math.abs(p.savings_usd || 0))"></td>
                                        </tr>
                                    </template>
                                </tbody>
                            </table>
                        </div>
                        <div class="mt-2 text-xs text-gray-600">
                            Saved = measured baseline-model cost minus served cost, on rerouted rows with provider-reported usage.
                            The requested model is a ceiling; holdout rows stay unrouted as the control arm.
                        </div>
                    </div>
                </template>

                <!-- Recent Requests Table (with expandable rows) -->
                <div class="bg-surface rounded-lg border border-border overflow-hidden mb-6">
                    <div class="px-4 py-3 border-b border-border flex justify-between items-center">
                        <span class="text-sm font-medium text-gray-300">Recent Requests</span>
                        <span class="text-xs text-gray-500">Last 25 &mdash; click row to expand</span>
                    </div>
                    <div class="overflow-x-auto">
                        <div>
                            <!-- Header -->
                            <div class="grid text-xs text-gray-500 uppercase tracking-wide border-b border-border"
                                 style="grid-template-columns: 2rem 12fr 22fr 15fr 12fr 10fr 14fr">
                                <div class="px-2 py-3"></div>
                                <div class="px-4 py-3 font-medium">Time</div>
                                <div class="px-4 py-3 font-medium">Model</div>
                                <div class="px-4 py-3 font-medium text-right">Input</div>
                                <div class="px-4 py-3 font-medium text-right">Output</div>
                                <div class="px-4 py-3 font-medium text-right"
                                     title="Message-compression share of this request only. Tool-schema deferral, cache discounts and routing savings are counted in the headline cards, not per row.">Msg&nbsp;Saved</div>
                                <div class="px-4 py-3 font-medium text-right">Latency</div>
                            </div>
                            <!-- Data rows -->
                            <div class="divide-y divide-border">
                                <template x-for="req in (stats.recent_requests || [])" :key="req.request_id">
                                    <div>
                                        <div class="cursor-pointer" role="button" tabindex="0"
                                             :aria-expanded="!!expandedRows[req.request_id]"
                                             :aria-label="'Request at ' + formatTime(req.timestamp) + ', ' + truncateModel(req.model) + ', ' + req.savings_percent.toFixed(0) + ' percent saved. Toggle details'"
                                             @click="toggleExpanded(req.request_id)"
                                             @keydown.enter.prevent="toggleExpanded(req.request_id)"
                                             @keydown.space.prevent="toggleExpanded(req.request_id)">
                                            <div class="grid hover:bg-border/30 transition-colors"
                                                 style="grid-template-columns: 2rem 12fr 22fr 15fr 12fr 10fr 14fr">
                                                <div class="px-2 py-3 text-gray-500 flex items-center justify-center">
                                                    <span aria-hidden="true" x-text="expandedRows[req.request_id] ? '-' : '+'"></span>
                                                </div>
                                                <div class="px-4 py-3 font-mono text-gray-400 truncate" x-text="formatTime(req.timestamp)"></div>
                                                <div class="px-4 py-3 min-w-0">
                                                    <span class="px-2 py-0.5 bg-border rounded text-xs truncate" x-text="truncateModel(req.model)"></span>
                                                </div>
                                                <div class="px-4 py-3 text-right font-mono tabular-nums" x-text="formatNumber(req.input_tokens_optimized)"></div>
                                                <div class="px-4 py-3 text-right font-mono tabular-nums" x-text="formatNumber(req.output_tokens || 0)"></div>
                                                <div class="px-4 py-3 text-right">
                                                    <span class="text-accent font-mono tabular-nums" x-text="req.savings_percent.toFixed(0) + '%'"></span>
                                                </div>
                                                <div class="px-4 py-3 text-right font-mono tabular-nums text-gray-400" x-text="(req.total_latency_ms || 0).toFixed(0) + 'ms'"></div>
                                            </div>
                                        </div>
                                        <!-- Expanded detail row -->
                                        <template x-if="expandedRows[req.request_id]">
                                            <div class="px-8 py-4 border-t border-border" style="background: var(--card-alt-bg);">
                                                <div class="grid grid-cols-2 lg:grid-cols-4 gap-4 text-xs">
                                                    <div>
                                                        <div class="text-gray-500 uppercase tracking-wide mb-1">Original Tokens</div>
                                                        <div class="font-mono" x-text="formatNumber(req.input_tokens_original)"></div>
                                                    </div>
                                                    <div>
                                                        <div class="text-gray-500 uppercase tracking-wide mb-1">Compressed Tokens</div>
                                                        <div class="font-mono" x-text="formatNumber(req.input_tokens_optimized)"></div>
                                                    </div>
                                                    <div>
                                                        <div class="text-gray-500 uppercase tracking-wide mb-1">Tokens Removed</div>
                                                        <div class="font-mono text-accent" x-text="formatNumber(req.tokens_saved)"></div>
                                                    </div>
                                                    <div>
                                                        <div class="text-gray-500 uppercase tracking-wide mb-1">Optimization Time</div>
                                                        <div class="font-mono" x-text="(req.optimization_latency_ms || 0).toFixed(0) + 'ms'"></div>
                                                    </div>
                                                </div>
                                                <!-- Transforms Applied -->
                                                <template x-if="(req.transforms_applied || []).length > 0">
                                                    <div class="mt-3">
